async function main(ctx) {
  const resp = ctx.lastOutputOf('get_template') || {};
  const initialArgs = ctx.lastOutputOf('__initial__') || {};

  const connectorId = initialArgs.connectorId;
  const includeDescriptions = initialArgs.includeDescriptions === true;

  const body = resp.body;
  if (!body || body.success !== true) {
    throw new Error(`Failed to list actions for connector template: ${connectorId}`);
  }

  const data = body.data ?? {};
  const actions = Array.isArray(data.actions)
    ? data.actions
    : Array.isArray(data.items)
      ? data.items
      : Array.isArray(data.results)
        ? data.results
        : Array.isArray(data)
     ? data
       : [];

  const endpointList = (actions || [])
  .map((a) => {
      const name = a?.name ?? a?.actionName ?? a?.action?.name;
   const description = a?.description ?? a?.action?.description ?? '';

      if (!name) return null;
      return includeDescriptions ? { name, description } : name;
    })
    .filter(Boolean);

  // Extract pagination metadata from API response
  const total = data.total ?? endpointList.length;
  const limit = data.limit ?? initialArgs.limit ?? endpointList.length;
  const offset = data.offset ?? initialArgs.offset ?? 0;
  const hasMore = (offset + endpointList.length) < total;

  return {
    connectorId,
    endpoints: endpointList,
    count: endpointList.length,
    total,
    limit,
    offset,
    hasMore
  };
}
